// AUTO-GENERATED by scripts/generate-registry.mjs — DO NOT EDIT.

export const pluginChangelogSources: Record<string, Partial<Record<string, string>>> = {
  "myvault": {"en":"# Changelog — My vault\n\n## 0.1.0\n\n- Keep private information in vault entries: a note, secret fields (like PINs) and files, encrypted on your device before they are saved.\n- Each entry opens only with its vault key (shown once to you) and the answers to three questions you choose: a date, text, a number, one or several choices.\n- Keep entries private forever, or choose people from your DevQuake referrals who receive the key if you do not use DevQuake for a number of days or months (optionally not before a date). You are warned by email before.\n- Every try to open an entry is recorded; after 3 wrong tries it is locked for 36 hours, you get an email and can review who tried and what they answered, and unlock it.\n","de":"# Änderungen — Mein Tresor\n\n## 0.1.0\n\n- Bewahre private Informationen in Tresoreinträgen auf: eine Notiz, geheime Felder (etwa PINs) und Dateien, verschlüsselt auf deinem Gerät, bevor sie gespeichert werden.\n- Jeder Eintrag öffnet sich nur mit seinem Tresorschlüssel (dir einmal angezeigt) und den Antworten auf drei Fragen deiner Wahl: ein Datum, Text, eine Zahl, eine oder mehrere Auswahlen.\n- Halte Einträge für immer privat oder wähle Personen aus deinen DevQuake-Empfehlungen, die den Schlüssel bekommen, wenn du DevQuake eine Anzahl von Tagen oder Monaten nicht nutzt (optional nicht vor einem Datum). Vorher wirst du per E-Mail gewarnt.\n- Jeder Versuch, einen Eintrag zu öffnen, wird festgehalten; nach 3 falschen Versuchen ist er 36 Stunden gesperrt, du bekommst eine E-Mail, siehst, wer es versucht und was geantwortet hat, und kannst ihn entsperren.\n","ro":"# Modificări — Seiful meu\n\n## 0.1.0\n\n- Păstrează informații private în intrări de seif: o notă, câmpuri secrete (de exemplu PIN-uri) și fișiere, criptate pe dispozitivul tău înainte de a fi salvate.\n- Fiecare intrare se deschide doar cu cheia ei de seif (afișată o singură dată) și cu răspunsurile la trei întrebări alese de tine: o dată, text, un număr, una sau mai multe variante.\n- Păstrează intrările private pentru totdeauna sau alege persoane din recomandările tale DevQuake care primesc cheia dacă nu folosești DevQuake un număr de zile sau luni (opțional nu înainte de o dată). Ești avertizat înainte prin e-mail.\n- Fiecare încercare de deschidere este înregistrată; după 3 încercări greșite intrarea este blocată 36 de ore, primești un e-mail, vezi cine a încercat și ce a răspuns și o poți debloca.\n","hu":"# Változások — Széfem\n\n## 0.1.0\n\n- Őrizz privát adatokat széfbejegyzésekben: jegyzetet, titkos mezőket (például PIN-kódokat) és fájlokat, amelyeket mentés előtt az eszközödön titkosítunk.\n- Minden bejegyzés csak a széfkulcsával (egyszer mutatjuk meg neked) és az általad választott három kérdés válaszaival nyílik meg: dátum, szöveg, szám, egy vagy több választás.\n- A bejegyzések örökre privátak maradhatnak, vagy kiválaszthatsz embereket a DevQuake-ajánlásaid közül, akik megkapják a kulcsot, ha bizonyos számú napig vagy hónapig nem használod a DevQuake-et (nem kötelezően egy dátum előtt nem). Előtte e-mailben figyelmeztetünk.\n- Minden megnyitási próbálkozást rögzítünk; 3 hibás próbálkozás után a bejegyzés 36 órára zárolódik, e-mailt kapsz, látod, ki próbálkozott és mit válaszolt, és feloldhatod.\n"},
  "shopping": {"en":"# Changelog: Shared shopping lists\n\n## 0.9.0\n\n- While shopping, **Correct price** saves the price on the shelf; the planned price is kept next to it.\n- New in Statistics: **Prices over time**, how the prices of your products change and how close your planned prices were.\n- Copy lists to other days: one list to a day, a week or a month, a whole week to the rest of the month, or a whole month to the rest of the year.\n- In shopping mode, adding a product is folded away at the top, so the list comes first.\n- Notifications: **Clear all**, or remove them one by one; the list always fits the screen.\n- A tidier toolbar on every screen: the app’s name (tap it for the start page), full screen and the DevQuake mark. The manual and version notes moved to the bottom of the page; your language and theme are set in your DevQuake account.\n\n## 0.8.0\n\n- A full screen button in the toolbar, where your browser allows it (not on iPhone).\n\n## 0.7.0\n\n- The app's logo is shown next to its name in the toolbar and as the browser tab icon.\n- New to the app? You can try it free for 24 hours before subscribing.\n\n## 0.6.0\n\n- The app is now available in German, Romanian and Hungarian as well as English. Pick a\n  language with the globe in the toolbar. DevQuake remembers your choice. On your first visit\n  it uses your browser's language if it is one of these, and English otherwise.\n- Everything is translated: the screens, the user manual, notifications and error messages.\n  Dates, weekdays and prices are written the way your language writes them.\n- Each language has its own address (for example /de/help), so search engines can show the\n  manual in your language.\n\n## 0.5.1\n\n- The buttons on the Today screen stay readable when you point at them in the dark theme.\n- The user manual now explains who can see your lists: only you and the people on each list.\n\n## 0.5.0\n\n- The owner of a list can delete it from **Share & settings**. It disappears for everyone on\n  it, with its invite links, notifications and product photos.\n- Your statistics stay the same after a list is deleted: what was planned and bought on it\n  still counts for everyone who was on it.\n- If a list is deleted while you have it open, you see a short message and a link back to\n  your lists.\n\n## 0.4.1\n\n- The user manual can be read without an account, so you can see how the app works before\n  signing up. It is also linked from the app's card on DevQuake.\n\n## 0.4.0\n\n- **Not needed**: strike out a product that is no longer needed. If it was already bought, it\n  stays in the list with a darker background and a 🙃, and statistics show the money spent on\n  things that were not needed.\n- **Notifications** inside the app: a bell with what your friends did on shared lists, pop-ups\n  for new changes and, if you allow it, system notifications while the app is open in a\n  background tab.\n- The app's version is shown in the toolbar and footer; click it to see what changed.\n\n## 0.3.0\n\n- Product photos: add one when creating or editing a product. Photos are made smaller on your\n  device before uploading, and only people on the list can see them.\n- Suggestions from your own shopping: the product field suggests what you bought before (accents\n  do not matter) and can fill in the whole row: unit, quantity, last price, description, store\n  and photo.\n- \"Usual products\": one tap adds a frequently bought product with everything from last time.\n- The home screen (Today, Calendar, Statistics) now updates by itself when anything changes on\n  your lists, like open lists already did.\n\n## 0.2.0\n\n- Every list has a shopping date (date picker, today by default).\n- Home screen with swipeable tabs: **Today** (today's lists with products, prices and totals per\n  store), **Calendar** (week, month and year views of all lists), **New list** (create or join)\n  and **Statistics** (totals per currency, stores, spending per month, most bought products with\n  price history, and how often each friend joined your lists).\n- Products need a name and a unit; the quantity is optional (counts as 1).\n- A user manual, opened from **Manual** in the toolbar.\n\n## 0.1.0\n\n- Shared shopping lists with members, invitations, stores and products.\n- Lists with a currency; products with quantity, unit, price per unit and description; totals\n  per store, \"still to buy\" and the whole list; shopping mode; clearing bought products.\n- Stores with name, type, location and description; store types from a catalogue (food,\n  home improvement, electronics, apparel, health and beauty), filled in automatically for\n  well-known chains.\n- Sharing by invite link, code or QR code (which you can renew), and by adding friends you\n  invited to DevQuake with one tap.\n- Changes by others appear on an open list within a few seconds.\n- Your lists are handed over or removed properly when you delete your DevQuake account.\n","de":"# Änderungen: Gemeinsame Einkaufslisten\n\n## 0.9.0\n\n- Beim Einkaufen speichert **Preis korrigieren** den Preis am Regal; der geplante Preis bleibt daneben erhalten.\n- Neu in der Statistik: **Preise im Zeitverlauf**, wie sich die Preise deiner Produkte ändern und wie nah deine geplanten Preise lagen.\n- Listen auf andere Tage kopieren: eine Liste auf einen Tag, eine Woche oder einen Monat, eine ganze Woche auf den Rest des Monats oder einen ganzen Monat auf den Rest des Jahres.\n- Im Einkaufsmodus ist das Hinzufügen eines Produkts oben eingeklappt, damit die Liste zuerst kommt.\n- Benachrichtigungen: **Alle löschen** oder einzeln entfernen; die Liste passt immer auf den Bildschirm.\n- Eine aufgeräumte Werkzeugleiste auf jedem Bildschirm: der Name der App (antippen führt zum Start), Vollbild und das DevQuake-Zeichen. Anleitung und Versionshinweise stehen jetzt unten auf der Seite; Sprache und Design stellst du in deinem DevQuake-Konto ein.\n\n## 0.8.0\n\n- Ein Vollbild-Knopf in der Leiste, wo dein Browser es erlaubt (nicht auf dem iPhone).\n\n## 0.7.0\n\n- Das Logo der App steht in der Leiste neben ihrem Namen und ist das Symbol im Browser-Tab.\n- Neu hier? Du kannst die App vor dem Abonnieren 24 Stunden kostenlos testen.\n\n## 0.6.0\n\n- Die App gibt es jetzt auch auf Deutsch, Rumänisch und Ungarisch, nicht nur auf Englisch.\n  Wähle die Sprache mit dem Globus in der Leiste. DevQuake merkt sich deine Wahl. Beim ersten\n  Besuch wird die Sprache deines Browsers genutzt, wenn sie eine davon ist, sonst Englisch.\n- Alles ist übersetzt: die Bildschirme, die Anleitung, Benachrichtigungen und Fehlermeldungen.\n  Datum, Wochentage und Preise werden so geschrieben, wie es in deiner Sprache üblich ist.\n- Jede Sprache hat ihre eigene Adresse (zum Beispiel /de/help), damit Suchmaschinen die\n  Anleitung in deiner Sprache zeigen können.\n\n## 0.5.1\n\n- Die Schaltflächen auf dem Bildschirm Heute bleiben im dunklen Design lesbar, wenn du mit der\n  Maus darauf zeigst.\n- Die Anleitung erklärt jetzt, wer deine Listen sehen kann: nur du und die Personen auf der\n  jeweiligen Liste.\n\n## 0.5.0\n\n- Der Inhaber einer Liste kann sie unter **Teilen & Einstellungen** löschen. Sie verschwindet\n  für alle auf ihr, mit ihren Einladungslinks, Benachrichtigungen und Produktfotos.\n- Deine Statistik bleibt gleich, wenn eine Liste gelöscht wird: Was darauf geplant und gekauft\n  wurde, zählt weiter für alle, die auf ihr waren.\n- Wird eine Liste gelöscht, während du sie geöffnet hast, siehst du einen kurzen Hinweis und\n  einen Link zurück zu deinen Listen.\n\n## 0.4.1\n\n- Die Anleitung kann ohne Konto gelesen werden, so siehst du vor der Anmeldung, wie die App\n  funktioniert. Sie ist auch auf der Karte der App auf DevQuake verlinkt.\n\n## 0.4.0\n\n- **Nicht gebraucht**: Streiche ein Produkt, das nicht mehr gebraucht wird. War es schon\n  gekauft, bleibt es mit dunklerem Hintergrund und einem 🙃 auf der Liste, und die Statistik\n  zeigt das Geld, das für nicht Gebrauchtes ausgegeben wurde.\n- **Benachrichtigungen** in der App: eine Glocke mit dem, was deine Freunde auf gemeinsamen\n  Listen gemacht haben, Hinweise zu neuen Änderungen und, wenn du es erlaubst,\n  Systembenachrichtigungen, während die App in einem Tab im Hintergrund geöffnet ist.\n- Die Version der App wird in der Leiste und in der Fußzeile gezeigt; klicke darauf, um zu\n  sehen, was sich geändert hat.\n\n## 0.3.0\n\n- Produktfotos: Füge beim Erstellen oder Bearbeiten eines Produkts eines hinzu. Fotos werden\n  vor dem Hochladen auf deinem Gerät verkleinert, und nur Personen auf der Liste können sie\n  sehen.\n- Vorschläge aus deinen eigenen Einkäufen: Das Produktfeld schlägt vor, was du schon gekauft\n  hast (Akzente spielen keine Rolle), und kann die ganze Zeile ausfüllen: Einheit, Menge,\n  letzter Preis, Beschreibung, Geschäft und Foto.\n- „Übliche Produkte“: Ein Tippen fügt ein häufig gekauftes Produkt mit allem vom letzten Mal\n  hinzu.\n- Der Startbildschirm (Heute, Kalender, Statistik) aktualisiert sich jetzt von selbst, wenn\n  sich auf deinen Listen etwas ändert, wie es geöffnete Listen schon taten.\n\n## 0.2.0\n\n- Jede Liste hat ein Einkaufsdatum (Datumsauswahl, standardmäßig heute).\n- Startbildschirm mit Tabs zum Wischen: **Heute** (die heutigen Listen mit Produkten, Preisen\n  und Summen pro Geschäft), **Kalender** (Wochen-, Monats- und Jahresansicht aller Listen),\n  **Neue Liste** (erstellen oder beitreten) und **Statistik** (Summen pro Währung, Geschäfte,\n  Ausgaben pro Monat, am häufigsten gekaufte Produkte mit Preisverlauf und wie oft jeder Freund\n  auf deinen Listen war).\n- Produkte brauchen einen Namen und eine Einheit; die Menge ist optional (zählt als 1).\n- Eine Anleitung, geöffnet über **Anleitung** in der Leiste.\n\n## 0.1.0\n\n- Gemeinsame Einkaufslisten mit Mitgliedern, Einladungen, Geschäften und Produkten.\n- Listen mit einer Währung; Produkte mit Menge, Einheit, Preis pro Einheit und Beschreibung;\n  Summen pro Geschäft, „noch zu kaufen“ und für die ganze Liste; Einkaufsmodus; Entfernen\n  gekaufter Produkte.\n- Geschäfte mit Name, Art, Ort und Beschreibung; Arten von Geschäften aus einem Katalog\n  (Lebensmittel, Heimwerken, Elektronik, Bekleidung, Gesundheit und Schönheit), bei bekannten\n  Ketten automatisch ausgefüllt.\n- Teilen per Einladungslink, Code oder QR-Code (den du erneuern kannst) und durch Hinzufügen\n  von Freunden, die du zu DevQuake eingeladen hast, mit einem Tippen.\n- Änderungen anderer erscheinen auf einer geöffneten Liste innerhalb weniger Sekunden.\n- Deine Listen werden ordnungsgemäß übergeben oder entfernt, wenn du dein DevQuake-Konto\n  löschst.\n","ro":"# Noutăți: Liste de cumpărături comune\n\n## 0.9.0\n\n- La cumpărături, **Corectează prețul** salvează prețul de pe raft; prețul planificat rămâne alături.\n- Nou în Statistici: **Prețurile în timp**, cum se schimbă prețurile produselor tale și cât de aproape au fost prețurile planificate.\n- Copiază liste în alte zile: o listă într-o zi, o săptămână sau o lună, o săptămână întreagă în restul lunii ori o lună întreagă în restul anului.\n- În modul cumpărături, adăugarea unui produs este restrânsă sus, ca lista să fie prima.\n- Notificări: **Șterge tot** sau elimină-le una câte una; lista încape mereu pe ecran.\n- O bară de sus mai simplă pe fiecare ecran: numele aplicației (atinge-l pentru pagina de start), ecranul complet și semnul DevQuake. Manualul și notele de versiune s-au mutat jos pe pagină; limba și tema le setezi în contul tău DevQuake.\n\n## 0.8.0\n\n- Un buton de ecran complet în bară, acolo unde browserul îl permite (nu pe iPhone).\n\n## 0.7.0\n\n- Logoul aplicației apare lângă numele ei în bară și ca pictogramă a filei din browser.\n- Ești nou? Poți încerca aplicația gratuit 24 de ore înainte să te abonezi.\n\n## 0.6.0\n\n- Aplicația este acum disponibilă și în germană, română și maghiară, pe lângă engleză. Alege\n  limba de la globul din bară. DevQuake ține minte alegerea ta. La prima vizită folosește limba\n  browserului tău, dacă este una dintre acestea, altfel engleza.\n- Totul este tradus: ecranele, manualul de utilizare, notificările și mesajele de eroare.\n  Datele, zilele săptămânii și prețurile sunt scrise așa cum se scriu în limba ta.\n- Fiecare limbă are propria adresă (de exemplu /ro/help), ca motoarele de căutare să poată\n  arăta manualul în limba ta.\n\n## 0.5.1\n\n- Butoanele de pe ecranul Azi rămân lizibile în tema întunecată când treci cu mouse-ul peste\n  ele.\n- Manualul de utilizare explică acum cine îți poate vedea listele: doar tu și persoanele de pe\n  fiecare listă.\n\n## 0.5.0\n\n- Proprietarul unei liste o poate șterge din **Distribuire și setări**. Lista dispare pentru\n  toți cei de pe ea, împreună cu linkurile de invitație, notificările și pozele produselor.\n- Statisticile tale rămân la fel după ștergerea unei liste: ce s-a planificat și cumpărat pe ea\n  contează în continuare pentru toți cei care au fost pe ea.\n- Dacă o listă este ștearsă în timp ce o ai deschisă, vezi un scurt mesaj și un link înapoi la\n  listele tale.\n\n## 0.4.1\n\n- Manualul de utilizare poate fi citit fără cont, ca să vezi cum funcționează aplicația înainte\n  să te înregistrezi. Are link și de pe cardul aplicației pe DevQuake.\n\n## 0.4.0\n\n- **Nu mai trebuie**: taie un produs de care nu mai e nevoie. Dacă fusese deja cumpărat,\n  rămâne pe listă cu un fundal mai închis și un 🙃, iar statisticile arată banii cheltuiți pe\n  lucruri care nu mai trebuiau.\n- **Notificări** în aplicație: un clopoțel cu ce au făcut prietenii tăi pe listele comune,\n  mesaje scurte pentru modificările noi și, dacă permiți, notificări de sistem cât timp\n  aplicația e deschisă într-o filă în fundal.\n- Versiunea aplicației apare în bară și în subsol; apasă pe ea ca să vezi ce s-a schimbat.\n\n## 0.3.0\n\n- Poze ale produselor: adaugă una când creezi sau editezi un produs. Pozele sunt micșorate pe\n  dispozitivul tău înainte de încărcare și doar persoanele de pe listă le pot vedea.\n- Sugestii din propriile cumpărături: câmpul produsului sugerează ce ai mai cumpărat\n  (diacriticele nu contează) și poate completa tot rândul: unitatea, cantitatea, ultimul preț,\n  descrierea, magazinul și poza.\n- „Produse obișnuite”: o atingere adaugă un produs cumpărat des, cu tot ce avea data trecută.\n- Ecranul principal (Azi, Calendar, Statistici) se actualizează acum singur când se schimbă\n  ceva pe listele tale, cum făceau deja listele deschise.\n\n## 0.2.0\n\n- Fiecare listă are o dată a cumpărăturilor (selector de dată, implicit azi).\n- Ecran principal cu file care se glisează: **Azi** (listele de azi cu produse, prețuri și\n  totaluri pe magazin), **Calendar** (vizualizare pe săptămână, lună și an a tuturor listelor),\n  **Listă nouă** (creează sau alătură-te) și **Statistici** (totaluri pe monedă, magazine,\n  cheltuieli pe lună, cele mai cumpărate produse cu istoricul prețurilor și cât de des a fost\n  fiecare prieten pe listele tale).\n- Produsele au nevoie de un nume și o unitate; cantitatea este opțională (contează ca 1).\n- Un manual de utilizare, deschis din **Manual** în bară.\n\n## 0.1.0\n\n- Liste de cumpărături comune, cu membri, invitații, magazine și produse.\n- Liste cu o monedă; produse cu cantitate, unitate, preț pe unitate și descriere; totaluri pe\n  magazin, „rămas de cumpărat” și pentru toată lista; modul cumpărături; eliminarea produselor\n  cumpărate.\n- Magazine cu nume, tip, locație și descriere; tipuri de magazine dintr-un catalog (alimente,\n  bricolaj, electronice, îmbrăcăminte, sănătate și frumusețe), completate automat pentru\n  lanțurile cunoscute.\n- Distribuire prin link de invitație, cod sau cod QR (pe care îl poți reînnoi) și prin\n  adăugarea cu o atingere a prietenilor pe care i-ai invitat pe DevQuake.\n- Modificările făcute de alții apar pe o listă deschisă în câteva secunde.\n- Listele tale sunt predate sau șterse cum trebuie când îți ștergi contul DevQuake.\n","hu":"# Változások: Közös bevásárlólisták\n\n## 0.9.0\n\n- Vásárlás közben az **Ár javítása** elmenti a polcon látott árat; a tervezett ár mellette megmarad.\n- Új a statisztikában: **Árak az idő múlásával**, hogyan változnak a termékeid árai, és mennyire voltak pontosak a tervezett áraid.\n- Listák másolása más napokra: egy listát egy napra, egy hétre vagy egy hónapra, egy teljes hetet a hónap többi részére, vagy egy teljes hónapot az év többi részére.\n- Bevásárlás közben a termék hozzáadása felül össze van csukva, így a lista kerül előre.\n- Értesítések: **Összes törlése**, vagy eltávolítás egyenként; a lista mindig elfér a képernyőn.\n- Letisztultabb eszköztár minden képernyőn: az alkalmazás neve (koppints rá a kezdőlaphoz), a teljes képernyő és a DevQuake jele. Az útmutató és a verziójegyzetek az oldal aljára kerültek; a nyelvet és a témát a DevQuake-fiókodban állítod be.\n\n## 0.8.0\n\n- Teljes képernyő gomb a sávban, ahol a böngésző engedi (iPhone-on nem).\n\n## 0.7.0\n\n- Az alkalmazás logója megjelenik a neve mellett a sávban, és ez a böngészőlap ikonja is.\n- Új vagy? Feliratkozás előtt 24 órán át ingyen kipróbálhatod az alkalmazást.\n\n## 0.6.0\n\n- Az alkalmazás mostantól németül, románul és magyarul is elérhető, nem csak angolul. A nyelvet\n  a sávban lévő földgömbbel választhatod ki. A DevQuake megjegyzi a választásodat. Az első\n  látogatáskor a böngésződ nyelvét használja, ha az ezek egyike, különben az angolt.\n- Minden le van fordítva: a képernyők, az útmutató, az értesítések és a hibaüzenetek. A\n  dátumok, a hét napjai és az árak úgy jelennek meg, ahogy a te nyelveden szokás.\n- Minden nyelvnek saját címe van (például /hu/help), így a keresők a te nyelveden mutathatják\n  az útmutatót.\n\n## 0.5.1\n\n- A Ma képernyő gombjai sötét témában is olvashatók maradnak, amikor rájuk mutatsz.\n- Az útmutató most elmagyarázza, ki láthatja a listáidat: csak te és az adott lista tagjai.\n\n## 0.5.0\n\n- A lista tulajdonosa törölheti a listát a **Megosztás és beállítások** részben. A lista\n  mindenkinél eltűnik, a meghívó linkjeivel, értesítéseivel és termékfotóival együtt.\n- A statisztikád egy lista törlése után sem változik: ami rajta tervezve és megvéve volt,\n  továbbra is számít mindenkinek, aki rajta volt.\n- Ha egy listát akkor törölnek, amikor épp nyitva van nálad, egy rövid üzenetet és egy linket\n  látsz vissza a listáidhoz.\n\n## 0.4.1\n\n- Az útmutató fiók nélkül is olvasható, így regisztráció előtt megnézheted, hogyan működik az\n  alkalmazás. Az alkalmazás DevQuake-kártyájáról is elérhető.\n\n## 0.4.0\n\n- **Nem kell**: húzd ki azt a terméket, amelyre már nincs szükség. Ha már megvették, sötétebb\n  háttérrel és egy 🙃 jellel a listán marad, és a statisztika mutatja a feleslegesen költött\n  pénzt.\n- **Értesítések** az alkalmazásban: egy csengő azzal, amit a barátaid a közös listákon\n  csináltak, felugró üzenetek az új változásokról, és ha engedélyezed, rendszerértesítések,\n  amíg az alkalmazás egy háttérben lévő lapon nyitva van.\n- Az alkalmazás verziója megjelenik a sávban és a láblécben; kattints rá, hogy lásd, mi\n  változott.\n\n## 0.3.0\n\n- Termékfotók: adj hozzá egyet egy termék létrehozásakor vagy szerkesztésekor. A fotókat\n  feltöltés előtt az eszközödön kicsinyítjük, és csak a listán lévők láthatják őket.\n- Javaslatok a saját vásárlásaidból: a termékmező felajánlja, amit korábban vettél (az ékezetek\n  nem számítanak), és kitöltheti az egész sort: egység, mennyiség, utolsó ár, leírás, üzlet és\n  fotó.\n- „Szokásos termékek”: egy koppintás hozzáad egy gyakran vett terméket mindennel, ami legutóbb\n  volt.\n- A kezdőképernyő (Ma, Naptár, Statisztika) mostantól magától frissül, ha valami változik a\n  listáidon, ahogy a megnyitott listák már eddig is.\n\n## 0.2.0\n\n- Minden listának van bevásárlási dátuma (dátumválasztó, alapból a mai nap).\n- Kezdőképernyő húzható fülekkel: **Ma** (a mai listák termékekkel, árakkal és üzletenkénti\n  összegekkel), **Naptár** (az összes lista heti, havi és éves nézetben), **Új lista**\n  (létrehozás vagy csatlakozás) és **Statisztika** (összegek pénznemenként, üzletek, havi\n  költés, a leggyakrabban vett termékek ártörténettel, és hogy melyik barátod milyen gyakran\n  volt a listáidon).\n- A termékeknek név és egység kell; a mennyiség nem kötelező (1-nek számít).\n- Útmutató, amely a sáv **Útmutató** pontjából nyílik.\n\n## 0.1.0\n\n- Közös bevásárlólisták tagokkal, meghívókkal, üzletekkel és termékekkel.\n- Listák pénznemmel; termékek mennyiséggel, egységgel, egységárral és leírással; összegek\n  üzletenként, „még megvenni” és a teljes listára; bevásárló mód; a megvett termékek törlése.\n- Üzletek névvel, típussal, hellyel és leírással; üzlettípusok katalógusból (élelmiszer,\n  barkács, elektronika, ruházat, egészség és szépség), az ismert láncoknál automatikusan\n  kitöltve.\n- Megosztás meghívó linkkel, kóddal vagy QR-kóddal (amelyet megújíthatsz), és a DevQuake-re\n  általad meghívott barátok egy koppintásos hozzáadásával.\n- Mások változásai néhány másodpercen belül megjelennek egy megnyitott listán.\n- A DevQuake-fiókod törlésekor a listáid rendben átadásra kerülnek vagy törlődnek.\n"},
  "utilities": {"en":"# Changelog — Utility bill manager\n\n## 0.3.0\n\n- Meter photos: take one with the camera or choose one from your photo library.\n- View-only members: the manager can let a family member see every bill without having a share or paying.\n- Confirmed payments are locked, and the person who paid gets an email with the whole bill, their consumption and share, and a link to the bill and its PDF.\n- A tidier toolbar on every screen: the app’s name (tap it for the start page), full screen and the DevQuake mark. The manual and version notes moved to the bottom of the page; your language and theme are set in your DevQuake account.\n\n## 0.2.0\n\n- Your address is now asked in parts (country, state or county, city, street, number and an optional apartment), with suggestions from OpenStreetMap as you type. If you saved an address before, you are asked to complete it once.\n\n## 0.1.0\n\n- Add your utilities (electricity, gas, water, heating, phone, cable TV, internet, online hosting, Xbox, Microsoft, Apple, Steam or anything else) and collect their bills month by month.\n- Upload the provider’s PDF: the app tries to read the total, consumption, unit price and due date; anything it cannot read you type into the same form.\n- Share a utility with an invite link, a QR code or directly with people from your DevQuake referrals. Only the people on a utility can see its bills.\n- “Individual meter required”: everyone sends a photo of their meter with the index for every bill; the app tries to read the index from the photo.\n- Fair split: consumption × unit price for each person, with anything the meters do not cover shared equally; without meters the bill is split equally.\n- The manager records what each person paid (cash, card or other); paying more or less is carried over to the next bill. Paid bills get a green check mark, others a warning.\n- Comments on every bill, a month and year calendar of your own part, and statistics on consumption, payments and prices per category.\n- Your name and address in your profile, shown only to the people you share a utility with.\n","de":"# Änderungen — Nebenkosten\n\n## 0.3.0\n\n- Zählerfotos: mit der Kamera aufnehmen oder aus der Mediathek wählen.\n- Mitglieder zum Ansehen: Die verwaltende Person kann ein Familienmitglied jede Rechnung sehen lassen, ohne dass es einen Anteil hat oder zahlt.\n- Bestätigte Zahlungen sind gesperrt, und wer bezahlt hat, bekommt eine E-Mail mit der ganzen Rechnung, dem eigenen Verbrauch und Anteil und einem Link zur Rechnung und ihrem PDF.\n- Eine aufgeräumte Werkzeugleiste auf jedem Bildschirm: der Name der App (antippen führt zum Start), Vollbild und das DevQuake-Zeichen. Anleitung und Versionshinweise stehen jetzt unten auf der Seite; Sprache und Design stellst du in deinem DevQuake-Konto ein.\n\n## 0.2.0\n\n- Deine Adresse wird jetzt in Teilen abgefragt (Land, Bundesland oder Kreis, Ort, Straße, Hausnummer und optional Wohnung), mit Vorschlägen aus OpenStreetMap beim Tippen. Hast du schon eine Adresse gespeichert, wirst du einmal gebeten, sie zu vervollständigen.\n\n## 0.1.0\n\n- Füge deine Versorger hinzu (Strom, Gas, Wasser, Heizung, Telefon, Kabelfernsehen, Internet, Online-Hosting, Xbox, Microsoft, Apple, Steam oder etwas anderes) und sammle ihre Rechnungen Monat für Monat.\n- Lade das PDF des Anbieters hoch: Die App versucht, Gesamtbetrag, Verbrauch, Preis pro Einheit und Fälligkeit zu lesen; was sie nicht lesen kann, tippst du im selben Formular ein.\n- Teile einen Versorger per Einladungslink, QR-Code oder direkt mit Personen aus deinen DevQuake-Empfehlungen. Nur die Personen eines Versorgers sehen seine Rechnungen.\n- „Eigener Zähler erforderlich“: Alle senden zu jeder Rechnung ein Foto ihres Zählers mit dem Zählerstand; die App versucht, den Zählerstand vom Foto zu lesen.\n- Faire Aufteilung: Verbrauch × Preis pro Einheit für jede Person, und was die Zähler nicht abdecken, wird gleichmäßig geteilt; ohne Zähler wird die Rechnung gleichmäßig geteilt.\n- Die verwaltende Person trägt ein, was jede Person bezahlt hat (bar, Karte oder anders); Mehr- oder Minderzahlungen werden auf die nächste Rechnung übertragen. Bezahlte Rechnungen bekommen ein grünes Häkchen, andere eine Warnung.\n- Kommentare zu jeder Rechnung, ein Monats- und Jahreskalender deines eigenen Anteils und Statistiken zu Verbrauch, Zahlungen und Preisen pro Kategorie.\n- Dein Name und deine Adresse im Profil, sichtbar nur für die Personen, mit denen du einen Versorger teilst.\n","ro":"# Modificări — Facturi utilități\n\n## 0.3.0\n\n- Fotografiile contorului: fă una cu camera sau alege una din galerie.\n- Membri doar pentru vizualizare: administratorul poate lăsa un membru al familiei să vadă fiecare factură fără să aibă parte sau să plătească.\n- Plățile confirmate sunt blocate, iar cel care a plătit primește un e-mail cu întreaga factură, consumul și partea sa și un link spre factură și PDF-ul ei.\n- O bară de sus mai simplă pe fiecare ecran: numele aplicației (atinge-l pentru pagina de start), ecranul complet și semnul DevQuake. Manualul și notele de versiune s-au mutat jos pe pagină; limba și tema le setezi în contul tău DevQuake.\n\n## 0.2.0\n\n- Adresa se cere acum pe părți (țara, județul sau regiunea, localitatea, strada, numărul și opțional apartamentul), cu sugestii din OpenStreetMap în timp ce scrii. Dacă ai salvat deja o adresă, ți se cere o singură dată s-o completezi.\n\n## 0.1.0\n\n- Adaugă-ți utilitățile (curent, gaz, apă, încălzire, telefon, televiziune prin cablu, internet, găzduire online, Xbox, Microsoft, Apple, Steam sau orice altceva) și strânge-le facturile lună de lună.\n- Încarcă PDF-ul furnizorului: aplicația încearcă să citească totalul, consumul, prețul unitar și scadența; ce nu poate citi introduci în același formular.\n- Partajează o utilitate cu un link de invitație, un cod QR sau direct cu persoane din recomandările tale DevQuake. Doar cei de pe o utilitate îi văd facturile.\n- „Contor individual obligatoriu”: fiecare trimite la fiecare factură o fotografie a contorului cu indexul; aplicația încearcă să citească indexul din fotografie.\n- Împărțire corectă: consum × preț unitar pentru fiecare, iar ce nu acoperă contoarele se împarte egal; fără contoare, factura se împarte egal.\n- Administratorul înregistrează cât a plătit fiecare (numerar, card sau altfel); plățile mai mari sau mai mici se reportează la factura următoare. Facturile plătite primesc bifa verde, celelalte un avertisment.\n- Comentarii la fiecare factură, un calendar lunar și anual al părții tale și statistici despre consum, plăți și prețuri pe categorii.\n- Numele și adresa ta în profil, vizibile doar persoanelor cu care împarți o utilitate.\n","hu":"# Változások — Közműszámlák\n\n## 0.3.0\n\n- Mérőóra-fotók: készíts egyet a kamerával, vagy válassz a galériából.\n- Csak megtekintő tagok: a kezelő megengedheti egy családtagnak, hogy minden számlát lásson anélkül, hogy része lenne vagy fizetne.\n- A visszaigazolt fizetések zárolva vannak, a fizető pedig e-mailt kap a teljes számláról, a saját fogyasztásáról és részéről, valamint egy linket a számlához és a PDF-jéhez.\n- Letisztultabb eszköztár minden képernyőn: az alkalmazás neve (koppints rá a kezdőlaphoz), a teljes képernyő és a DevQuake jele. Az útmutató és a verziójegyzetek az oldal aljára kerültek; a nyelvet és a témát a DevQuake-fiókodban állítod be.\n\n## 0.2.0\n\n- A címedet most részenként kérjük (ország, megye vagy tartomány, település, utca, házszám és nem kötelezően lakás), gépelés közben az OpenStreetMap javaslataival. Ha már mentettél címet, egyszer megkérünk, hogy egészítsd ki.\n\n## 0.1.0\n\n- Add hozzá a közműveidet (villany, gáz, víz, fűtés, telefon, kábeltévé, internet, online tárhely, Xbox, Microsoft, Apple, Steam vagy bármi más), és gyűjtsd a számláikat hónapról hónapra.\n- Töltsd fel a szolgáltató PDF-jét: az alkalmazás megpróbálja kiolvasni a végösszeget, a fogyasztást, az egységárat és a határidőt; amit nem tud, azt ugyanabban az űrlapban írod be.\n- Oszd meg a közművet meghívó linkkel, QR-kóddal, vagy közvetlenül a DevQuake-ajánlásaid közül. A számlákat csak a közmű tagjai látják.\n- „Egyéni mérőóra kötelező”: mindenki minden számlához fényképet küld a mérőórájáról a mérőállással; az alkalmazás megpróbálja kiolvasni a mérőállást a fényképről.\n- Igazságos elosztás: mindenkinek fogyasztás × egységár, és amit a mérőórák nem fednek le, egyenlően oszlik el; mérőórák nélkül a számla egyenlően oszlik el.\n- A kezelő rögzíti, ki mennyit fizetett (készpénz, kártya vagy más); a több- vagy kevesebbfizetés átkerül a következő számlára. A kifizetett számlák zöld pipát kapnak, a többi figyelmeztetést.\n- Megjegyzések minden számlához, havi és éves naptár a saját részedről, és kategóriánkénti statisztika a fogyasztásról, a fizetésekről és az árakról.\n- A neved és a címed a profilban, csak azok látják, akikkel közművet osztasz meg.\n"},
  "workout": {"en":"# Changelog: Workout tracker\n\n## 0.11.0\n\n- A natural voice coach: the coach now speaks with real human-sounding voices in every language (an adult man or a woman: Ryan and Sonia in English, Conrad and Katja in German, Emil and Alina in Romanian, Tamás and Noémi in Hungarian), no matter which voices your device has. The male voice is clear and crisp. You can still choose your device's own voice in the speech settings.\n- The mute and speech settings buttons moved up to the toolbar, on the right of the app's name.\n\n## 0.10.0\n\n- The voice coach speaks clearly in German, Romanian and Hungarian: it uses the most natural voice your device has for the language, never an English voice reading other languages, and no longer distorts the voice to make it male or female.\n- Choose the exact voice of your device in the speech settings; if your device has no voice for your language, the settings tell you how to add one.\n- The speech settings always fit the screen, on phones too (portrait and landscape), and scroll when needed.\n- A tidier toolbar on every screen: the app’s name (tap it for the start page), full screen and the DevQuake mark. The manual and version notes moved to the bottom of the page; your language and theme are set in your DevQuake account.\n\n## 0.9.0\n\n- Progress photos: your starting photo now stays fixed, and next to it you step through your monthly photos with the arrows, the arrow keys or a swipe, to see how much you changed month by month. The slider view shows the two on top of each other.\n- At the end of every month, the home screen and Progress remind you to take the month’s photo. Missed it? You can still add last month’s photo during the first week of the new month.\n\n## 0.8.3\n\n- If your sign-in ends while you plan a workout, build a routine or create an exercise, what you entered is no longer lost: it stays on your device, a link takes you to sign in again, and afterwards the form is filled in as you left it.\n- A short hiccup on our side while checking your sign-in no longer asks you to sign in again; you are asked to try again in a moment instead.\n\n## 0.8.2\n\n- Your plan in your calendar on every device: iPhone, iPad and Mac add it to Calendar, computers download a file for Outlook or Windows Calendar, and Android (or Google Calendar on a computer) gets a link per workout that opens Google Calendar with it filled in.\n- After adding or changing a planned workout, you see what was added and are taken back to the top of the form.\n\n## 0.8.1\n\n- The male coach voice now works on every device: iPhones and Macs no longer pick one of their joke voices, and where there is no male voice for your language, a deeper one is made from the voice you have.\n- \"Add to my calendar\" now opens in the Calendar app on iPhone and iPad (in Safari, tap Add All).\n\n## 0.8.0\n\n- A full screen button in the toolbar, where your browser allows it (not on iPhone).\n\n## 0.7.0\n\n- A new voice style, **Crazy**: with the male voice an army drill sergeant, with the female voice\n  a bossy boss. Both push you through every set and to the end of your workout.\n- The male voice now always sounds male: if your phone has no male voice for your language, the\n  coach makes one with a deeper pitch (and a higher one for the female voice).\n- Your own exercises: name them, choose the movement, how they are measured, where, equipment\n  and muscles. The moving figure is chosen automatically. Use them in your own routines.\n- Reminders for your plan: an email at the start or 10, 30 or 60 minutes before, at your local\n  time, and a calendar file for your phone's calendar.\n- Children from 6 years old can have a profile; up to 12 they get easier body-weight exercises.\n- On tablets and phones held sideways, the workout screen fits: the figure and the buttons sit\n  side by side, and the time and progress stay at the top.\n\n## 0.6.0\n\n- Build your own routines: pick exercises, sets, repetitions, time or distance and rests, in any\n  order. Only you can see them, and they stay when your suggested routines are made again.\n  Change or delete them any time, or start from a copy of a suggested routine.\n- A weekly plan: put routines at a time of day, every day or on chosen weekdays, several a day if\n  you like. The app makes sure they never overlap, and your home screen shows today's plan with\n  a Start button.\n\n## 0.5.0\n\n- The app's logo is shown next to its name in the toolbar and as the browser tab icon.\n- New to the app? You can try it free for 24 hours before subscribing.\n\n## 0.4.0\n\n- A user manual, opened from **Manual** (the ? button) in the toolbar. It explains the setup,\n  a guided workout, the voice coach, the calendar, progress photos and the monthly email step by\n  step, and can be read before you sign up.\n\n## 0.3.0\n\n- A voice coach: during a workout your phone counts down before each exercise and at the end of\n  every rest, announces sets, rests and the next exercise, and cheers you on. Choose a female or\n  male voice and a calm, normal or motivational style, or mute it, from the toolbar.\n- Encouraging words during rests and after every workout, with what went better than last time\n  and your personal records.\n- A calendar of your workouts: see a day, a month or a year, with your time, calories, sets,\n  repetitions and streaks. Tap a day for its details.\n- Progress photos: add a starting photo when you set up (or later in your profile), a photo for\n  every month and year, and compare before and after. Only you can see them.\n- A monthly summary email on the 1st with your numbers and a link to your calendar. You can turn\n  it off in your profile.\n- Suggested repetitions now depend on how hard each exercise is: fewer for pull-ups, more for\n  calf raises.\n- You stay signed in while a workout is running.\n\n## 0.2.0\n\n- The workout tracker now makes routines for you. Tell it your year of birth, height and weight\n  (in cm or ft, kg or lb), your experience and your goal, and where you train: at the gym, at\n  home or outside. For home, tick the equipment you have.\n- You get three routines for each place, each starting with a warm-up, with an estimate of the\n  time and the calories. You can have them made again from your profile.\n- A guided workout made for your phone: a moving figure shows each exercise, the app suggests\n  how many repetitions to do, you enter how many you did, and it moves on to the next exercise\n  by itself, with rest timers in between.\n- What you enter is saved by itself after 10 seconds. Without a connection it waits on your\n  phone and is sent when you are back online.\n- After the workout you see the total time, the time for each exercise, the calories (an\n  estimate) and what the app suggests for next time.\n\n## 0.1.1\n\n- The app now has its own storage, ready for saving your workouts. Nothing changes for you\n  yet.\n\n## 0.1.0\n\n- The first preview of the workout tracker. You open it with your DevQuake account, without\n  signing in again.\n- A sample week shows what the app will look like. Logging your own workouts comes next.\n","de":"# Änderungen: Trainingstagebuch\n\n## 0.11.0\n\n- Ein natürlicher Sprach-Coach: Der Coach spricht jetzt in jeder Sprache mit echt menschlich klingenden Stimmen (ein erwachsener Mann oder eine Frau: Ryan und Sonia auf Englisch, Conrad und Katja auf Deutsch, Emil und Alina auf Rumänisch, Tamás und Noémi auf Ungarisch), egal welche Stimmen dein Gerät hat. Die Männerstimme klingt klar und frisch. In den Spracheinstellungen kannst du weiterhin die Stimme deines Geräts wählen.\n- Die Knöpfe zum Stummschalten und für die Spracheinstellungen sind nach oben in die Werkzeugleiste gewandert, rechts neben den Namen der App.\n\n## 0.10.0\n\n- Der Sprach-Coach spricht auf Deutsch, Rumänisch und Ungarisch deutlich: Er nutzt die natürlichste Stimme deines Geräts für die Sprache, nie eine englische Stimme für andere Sprachen, und verzerrt die Stimme nicht mehr, um sie männlich oder weiblich zu machen.\n- Wähle in den Spracheinstellungen die genaue Stimme deines Geräts; hat dein Gerät keine Stimme für deine Sprache, erklären die Einstellungen, wie du eine hinzufügst.\n- Die Spracheinstellungen passen immer auf den Bildschirm, auch auf dem Handy (hoch und quer), und lassen sich bei Bedarf scrollen.\n- Eine aufgeräumte Werkzeugleiste auf jedem Bildschirm: der Name der App (antippen führt zum Start), Vollbild und das DevQuake-Zeichen. Anleitung und Versionshinweise stehen jetzt unten auf der Seite; Sprache und Design stellst du in deinem DevQuake-Konto ein.\n\n## 0.9.0\n\n- Fortschrittsfotos: Dein Startfoto bleibt jetzt fest stehen, und daneben blätterst du mit den Pfeilen, den Pfeiltasten oder einem Wischen durch deine Monatsfotos, um zu sehen, wie sehr du dich Monat für Monat verändert hast. Die Ansicht „Schieberegler“ legt die beiden übereinander.\n- Am Ende jedes Monats erinnern dich die Startseite und „Fortschritt“ an das Foto des Monats. Verpasst? Das Foto des Vormonats kannst du noch in der ersten Woche des neuen Monats hinzufügen.\n\n## 0.8.3\n\n- Wenn deine Anmeldung abläuft, während du ein Training planst, eine Routine erstellst oder eine Übung anlegst, geht deine Eingabe nicht mehr verloren: Sie bleibt auf deinem Gerät, ein Link bringt dich zur erneuten Anmeldung, und danach ist das Formular so ausgefüllt, wie du es verlassen hast.\n- Eine kurze Störung bei uns beim Prüfen deiner Anmeldung verlangt keine erneute Anmeldung mehr; du wirst stattdessen gebeten, es gleich noch einmal zu versuchen.\n\n## 0.8.2\n\n- Dein Wochenplan in deinem Kalender auf jedem Gerät: iPhone, iPad und Mac fügen ihn dem Kalender hinzu, Computer laden eine Datei für Outlook oder den Windows-Kalender, und Android (oder Google Kalender am Computer) bekommt pro Training einen Link, der Google Kalender mit dem ausgefüllten Training öffnet.\n- Nach dem Hinzufügen oder Ändern eines geplanten Trainings siehst du, was hinzugefügt wurde, und kommst zurück zum Anfang des Formulars.\n\n## 0.8.1\n\n- Die männliche Trainerstimme funktioniert jetzt auf jedem Gerät: iPhones und Macs wählen keine ihrer Spaßstimmen mehr, und wo es für deine Sprache keine männliche Stimme gibt, wird aus der vorhandenen eine tiefere gemacht.\n- „In meinen Kalender“ öffnet sich jetzt auf iPhone und iPad in der Kalender-App (in Safari auf „Alle hinzufügen“ tippen).\n\n## 0.8.0\n\n- Ein Vollbild-Knopf in der Leiste, wo dein Browser es erlaubt (nicht auf dem iPhone).\n\n## 0.7.0\n\n- Ein neuer Stil für die Stimme, **Verrückt**: mit der männlichen Stimme ein Ausbilder vom\n  Militär, mit der weiblichen eine strenge Chefin. Beide treiben dich durch jeden Satz bis zum\n  Ende des Trainings.\n- Die männliche Stimme klingt jetzt immer männlich: Hat dein Handy keine männliche Stimme für\n  deine Sprache, macht der Trainer eine mit tieferer Tonlage (und eine höhere für die weibliche).\n- Eigene Übungen: Gib ihnen einen Namen, wähle Bewegung, Messart, Ort, Ausstattung und Muskeln.\n  Die bewegte Figur wird automatisch gewählt. Nutze sie in deinen eigenen Plänen.\n- Erinnerungen für deinen Wochenplan: eine E-Mail zu Beginn oder 10, 30 oder 60 Minuten vorher,\n  zu deiner Ortszeit, und eine Kalenderdatei für den Kalender deines Handys.\n- Kinder ab 6 Jahren können ein Profil haben; bis 12 bekommen sie leichtere Übungen mit dem\n  eigenen Körpergewicht.\n- Auf Tablets und quer gehaltenen Handys passt der Trainingsbildschirm: Figur und Knöpfe stehen\n  nebeneinander, Zeit und Fortschritt bleiben oben.\n\n## 0.6.0\n\n- Erstelle eigene Trainingspläne: Wähle Übungen, Sätze, Wiederholungen, Zeit oder Strecke und\n  Pausen in beliebiger Reihenfolge. Nur du siehst sie, und sie bleiben, wenn deine\n  Vorschläge neu erstellt werden. Ändere oder lösche sie jederzeit, oder starte mit einer Kopie\n  eines vorgeschlagenen Plans.\n- Ein Wochenplan: Lege Pläne auf eine Uhrzeit, jeden Tag oder an bestimmten Wochentagen, auch\n  mehrere an einem Tag. Die App sorgt dafür, dass sie sich nie überschneiden, und dein\n  Startbildschirm zeigt, was heute geplant ist, mit einem Start-Knopf.\n\n## 0.5.0\n\n- Das Logo der App steht in der Symbolleiste neben ihrem Namen und ist das Symbol im Browser-Tab.\n- Neu hier? Du kannst die App vor dem Abonnieren 24 Stunden kostenlos testen.\n\n## 0.4.0\n\n- Eine Anleitung, zu öffnen über **Anleitung** (der ?-Knopf) in der Symbolleiste. Sie erklärt\n  Schritt für Schritt die Einrichtung, ein geführtes Training, den Sprachtrainer, den Kalender,\n  die Fortschrittsfotos und die monatliche E-Mail und ist auch vor der Anmeldung lesbar.\n\n## 0.3.0\n\n- Ein Sprachtrainer: Während des Trainings zählt dein Handy vor jeder Übung und am Ende jeder\n  Pause herunter, sagt Sätze, Pausen und die nächste Übung an und feuert dich an. Wähle in der\n  Werkzeugleiste eine weibliche oder männliche Stimme und einen ruhigen, normalen oder\n  motivierenden Stil, oder schalte sie stumm.\n- Aufmunternde Worte in den Pausen und nach jedem Training, mit dem, was besser lief als beim\n  letzten Mal, und deinen persönlichen Rekorden.\n- Ein Kalender deiner Trainings: Sieh dir einen Tag, einen Monat oder ein Jahr an, mit Zeit,\n  Kalorien, Sätzen, Wiederholungen und Serien. Tippe auf einen Tag für die Details.\n- Fortschrittsfotos: Füge beim Einrichten (oder später im Profil) ein Startfoto hinzu, dazu ein\n  Foto für jeden Monat und jedes Jahr, und vergleiche vorher und nachher. Nur du siehst sie.\n- Eine monatliche Übersicht per E-Mail am 1. mit deinen Zahlen und einem Link zu deinem\n  Kalender. Du kannst sie in deinem Profil abschalten.\n- Die vorgeschlagenen Wiederholungen hängen jetzt davon ab, wie schwer eine Übung ist: weniger\n  bei Klimmzügen, mehr beim Wadenheben.\n- Du bleibst angemeldet, solange ein Training läuft.\n\n## 0.2.0\n\n- Das Trainingstagebuch erstellt jetzt Trainingspläne für dich. Gib dein Geburtsjahr, deine\n  Größe und dein Gewicht an (in cm oder ft, kg oder lb), deine Erfahrung und dein Ziel, und wo\n  du trainierst: im Fitnessstudio, zu Hause oder draußen. Für zu Hause hakst du an, welche\n  Ausstattung du hast.\n- Für jeden Ort bekommst du drei Pläne, jeweils mit Aufwärmen und einer Schätzung von Zeit und\n  Kalorien. In deinem Profil kannst du sie neu erstellen lassen.\n- Ein geführtes Training für dein Handy: Eine bewegte Figur zeigt jede Übung, die App schlägt\n  die Wiederholungen vor, du trägst ein, wie viele du geschafft hast, und sie geht von selbst\n  zur nächsten Übung weiter, mit Pausen-Timern dazwischen.\n- Was du einträgst, wird nach 10 Sekunden von selbst gespeichert. Ohne Verbindung wartet es auf\n  deinem Handy und wird gesendet, sobald du wieder online bist.\n- Nach dem Training siehst du die Gesamtzeit, die Zeit für jede Übung, die Kalorien (eine\n  Schätzung) und den Vorschlag der App für das nächste Mal.\n\n## 0.1.1\n\n- Die App hat jetzt einen eigenen Speicher, bereit für deine Trainings. Für dich ändert sich\n  noch nichts.\n\n## 0.1.0\n\n- Die erste Vorschau des Trainingstagebuchs. Du öffnest es mit deinem DevQuake-Konto, ohne\n  dich erneut anzumelden.\n- Eine Beispielwoche zeigt, wie die App aussehen wird. Als Nächstes kannst du deine eigenen\n  Trainings eintragen.\n","ro":"# Noutăți: Jurnal de antrenament\n\n## 0.11.0\n\n- Un antrenor vocal natural: antrenorul vorbește acum în fiecare limbă cu voci care sună cu adevărat omenesc (un bărbat adult sau o femeie: Ryan și Sonia în engleză, Conrad și Katja în germană, Emil și Alina în română, Tamás și Noémi în maghiară), indiferent ce voci are dispozitivul tău. Vocea masculină este clară și limpede. În setările vocii poți alege în continuare vocea dispozitivului.\n- Butoanele pentru oprirea vocii și pentru setările vocii s-au mutat sus, în bara de instrumente, în dreapta numelui aplicației.\n\n## 0.10.0\n\n- Antrenorul vocal vorbește clar în germană, română și maghiară: folosește cea mai naturală voce a dispozitivului pentru limba respectivă, niciodată o voce engleză pentru alte limbi, și nu mai deformează vocea ca s-o facă masculină sau feminină.\n- Alege vocea exactă a dispozitivului în setările vocii; dacă dispozitivul nu are o voce pentru limba ta, setările îți explică cum adaugi una.\n- Setările vocii încap mereu pe ecran, și pe telefon (vertical și orizontal), și se pot derula la nevoie.\n- O bară de sus mai simplă pe fiecare ecran: numele aplicației (atinge-l pentru pagina de start), ecranul complet și semnul DevQuake. Manualul și notele de versiune s-au mutat jos pe pagină; limba și tema le setezi în contul tău DevQuake.\n\n## 0.9.0\n\n- Fotografii de progres: fotografia de început rămâne acum fixă, iar alături răsfoiești fotografiile lunare cu săgețile, tastele săgeți sau glisând, ca să vezi cât te-ai schimbat lună de lună. Vederea „Glisor” le suprapune.\n- La sfârșitul fiecărei luni, pagina principală și „Progres” îți amintesc să faci fotografia lunii. Ai ratat-o? O poți adăuga pe cea a lunii trecute în prima săptămână a lunii noi.\n\n## 0.8.3\n\n- Dacă autentificarea ta expiră în timp ce planifici un antrenament, creezi o rutină sau un exercițiu, ce ai introdus nu se mai pierde: rămâne pe dispozitivul tău, un link te duce să te autentifici din nou, iar apoi formularul este completat cum l-ai lăsat.\n- O scurtă problemă de partea noastră la verificarea autentificării nu îți mai cere să te autentifici din nou; ești rugat în schimb să încerci din nou peste câteva momente.\n\n## 0.8.2\n\n- Planul tău în calendar pe orice dispozitiv: iPhone, iPad și Mac îl adaugă în Calendar, calculatoarele descarcă un fișier pentru Outlook sau Calendarul Windows, iar Android (sau Google Calendar pe calculator) primește câte un link pentru fiecare antrenament, care deschide Google Calendar cu antrenamentul completat.\n- După ce adaugi sau modifici un antrenament planificat, vezi ce s-a adăugat și ajungi înapoi la începutul formularului.\n\n## 0.8.1\n\n- Vocea masculină a antrenorului funcționează acum pe orice dispozitiv: iPhone-urile și Mac-urile nu mai aleg una dintre vocile lor amuzante, iar unde nu există o voce masculină pentru limba ta, se face una mai gravă din vocea disponibilă.\n- „Adaugă în calendarul meu” se deschide acum în aplicația Calendar pe iPhone și iPad (în Safari, apasă „Adaugă tot”).\n\n## 0.8.0\n\n- Un buton de ecran complet în bară, acolo unde browserul îl permite (nu pe iPhone).\n\n## 0.7.0\n\n- Un stil nou pentru voce, **Nebun**: cu vocea masculină un instructor de armată, cu cea\n  feminină o șefă autoritară. Amândoi te împing prin fiecare serie până la finalul\n  antrenamentului.\n- Vocea masculină sună acum mereu masculin: dacă telefonul nu are o voce masculină pentru limba\n  ta, antrenorul face una cu un ton mai grav (și una mai înaltă pentru vocea feminină).\n- Exerciții proprii: dă-le un nume, alege mișcarea, cum se măsoară, unde, echipamentul și\n  mușchii. Figurina animată este aleasă automat. Folosește-le în programele tale.\n- Mementouri pentru plan: un e-mail la început sau cu 10, 30 ori 60 de minute înainte, la ora ta\n  locală, și un fișier de calendar pentru calendarul telefonului.\n- Copiii de la 6 ani pot avea un profil; până la 12 ani primesc exerciții mai ușoare, cu\n  greutatea corpului.\n- Pe tablete și pe telefoane ținute orizontal, ecranul de antrenament încape: figurina și\n  butoanele stau una lângă alta, iar timpul și progresul rămân sus.\n\n## 0.6.0\n\n- Creează-ți propriile programe: alege exerciții, serii, repetări, timp sau distanță și pauze, în\n  orice ordine. Doar tu le vezi și rămân când programele sugerate sunt create din nou. Le poți\n  modifica sau șterge oricând, sau poți porni de la o copie a unui program sugerat.\n- Un plan săptămânal: pune programe la o anumită oră, în fiecare zi sau în anumite zile ale\n  săptămânii, chiar și mai multe pe zi. Aplicația are grijă să nu se suprapună, iar ecranul\n  principal îți arată planul de azi cu un buton Start.\n\n## 0.5.0\n\n- Logoul aplicației apare lângă numele ei în bara de instrumente și ca pictogramă a filei din browser.\n- Ești nou? Poți încerca aplicația gratuit 24 de ore înainte să te abonezi.\n\n## 0.4.0\n\n- Un manual de utilizare, deschis din **Manual** (butonul ?) din bara de instrumente. Explică pas\n  cu pas configurarea, un antrenament ghidat, antrenorul vocal, calendarul, fotografiile de\n  progres și e-mailul lunar și poate fi citit și înainte să te înscrii.\n\n## 0.3.0\n\n- Un antrenor vocal: în timpul antrenamentului, telefonul numără invers înaintea fiecărui\n  exercițiu și la sfârșitul fiecărei pauze, anunță seriile, pauzele și exercițiul următor și te\n  încurajează. Din bara de instrumente alegi o voce feminină sau masculină și un stil calm,\n  normal sau motivant, ori o oprești.\n- Cuvinte de încurajare în pauze și după fiecare antrenament, cu ce a mers mai bine decât data\n  trecută și recordurile tale personale.\n- Un calendar al antrenamentelor: vezi o zi, o lună sau un an, cu timpul, caloriile, seriile,\n  repetările și zilele la rând. Atinge o zi pentru detalii.\n- Fotografii de progres: adaugă o fotografie de început la configurare (sau mai târziu în\n  profil), câte o fotografie pentru fiecare lună și an, și compară înainte și după. Doar tu le\n  vezi.\n- Un rezumat lunar pe e-mail, pe 1 ale lunii, cu cifrele tale și un link spre calendar. Îl poți\n  opri din profil.\n- Repetările sugerate depind acum de cât de greu e fiecare exercițiu: mai puține la tracțiuni,\n  mai multe la ridicările pe vârfuri.\n- Rămâi autentificat cât timp rulează un antrenament.\n\n## 0.2.0\n\n- Jurnalul de antrenament îți creează acum programe. Spune-i anul nașterii, înălțimea și\n  greutatea (în cm sau ft, kg sau lb), experiența și obiectivul tău, și unde te antrenezi: la\n  sală, acasă sau afară. Pentru acasă, bifează echipamentul pe care îl ai.\n- Primești trei programe pentru fiecare loc, fiecare cu încălzire și cu o estimare a timpului\n  și a caloriilor. Le poți crea din nou din profilul tău.\n- Un antrenament ghidat, gândit pentru telefon: o figură animată arată fiecare exercițiu,\n  aplicația îți sugerează câte repetări să faci, tu introduci câte ai făcut, iar ea trece\n  singură la exercițiul următor, cu cronometre de pauză între ele.\n- Ce introduci se salvează singur după 10 secunde. Fără conexiune, datele așteaptă pe telefon\n  și se trimit când revii online.\n- După antrenament vezi timpul total, timpul fiecărui exercițiu, caloriile (o estimare) și ce\n  îți sugerează aplicația pentru data viitoare.\n\n## 0.1.1\n\n- Aplicația are acum propriul spațiu de stocare, pregătit pentru antrenamentele tale. Deocamdată\n  nu se schimbă nimic pentru tine.\n\n## 0.1.0\n\n- Prima previzualizare a jurnalului de antrenament. Îl deschizi cu contul tău DevQuake, fără\n  să te autentifici din nou.\n- O săptămână de exemplu arată cum va arăta aplicația. Urmează notarea propriilor antrenamente.\n","hu":"# Változások: Edzésnapló\n\n## 0.11.0\n\n- Természetes hangú edző: az edző mostantól minden nyelven valóban emberi hangon beszél (egy felnőtt férfi vagy egy nő: angolul Ryan és Sonia, németül Conrad és Katja, románul Emil és Alina, magyarul Tamás és Noémi), bármilyen hangok vannak is az eszközödön. A férfihang tiszta és friss. A beszédbeállításokban továbbra is választhatod az eszközöd saját hangját.\n- A némítás és a beszédbeállítások gombja felkerült az eszköztárba, az alkalmazás nevétől jobbra.\n\n## 0.10.0\n\n- A hangos edző érthetően beszél németül, románul és magyarul: az eszközöd legtermészetesebb hangját használja az adott nyelvhez, soha nem angol hangot más nyelvekhez, és már nem torzítja a hangot, hogy férfias vagy nőies legyen.\n- A beszédbeállításokban kiválaszthatod az eszközöd pontos hangját; ha nincs hang a nyelvedhez, a beállítások elmagyarázzák, hogyan adhatsz hozzá.\n- A beszédbeállítások mindig elférnek a képernyőn, telefonon is (álló és fekvő helyzetben), és szükség esetén görgethetők.\n- Letisztultabb eszköztár minden képernyőn: az alkalmazás neve (koppints rá a kezdőlaphoz), a teljes képernyő és a DevQuake jele. Az útmutató és a verziójegyzetek az oldal aljára kerültek; a nyelvet és a témát a DevQuake-fiókodban állítod be.\n\n## 0.9.0\n\n- Haladásfotók: a kezdő fotód most rögzítve marad, mellette pedig a nyilakkal, a nyílbillentyűkkel vagy húzással lapozhatsz a havi fotóid között, hogy lásd, mennyit változtál hónapról hónapra. A „Csúszka” nézet egymásra helyezi a kettőt.\n- Minden hónap végén a kezdőlap és a „Fejlődés” oldal emlékeztet a havi fotóra. Kimaradt? Az előző hónap fotóját még az új hónap első hetében hozzáadhatod.\n\n## 0.8.3\n\n- Ha lejár a bejelentkezésed, miközben edzést tervezel, rutint készítesz vagy gyakorlatot hozol létre, a beírtak már nem vesznek el: az eszközödön maradnak, egy link visz az újbóli bejelentkezéshez, utána pedig az űrlap úgy van kitöltve, ahogy hagytad.\n- Ha nálunk rövid zavar van a bejelentkezésed ellenőrzésekor, már nem kérünk újbóli bejelentkezést; helyette arra kérünk, próbáld újra egy kicsit később.\n\n## 0.8.2\n\n- A heti terved a naptáradban minden eszközön: iPhone, iPad és Mac a Naptárhoz adja, számítógépen letöltődik egy fájl az Outlookhoz vagy a Windows Naptárhoz, Androidon (vagy Google Naptárhoz számítógépen) pedig minden edzéshez van egy link, amely kitöltve nyitja meg a Google Naptárat.\n- Egy tervezett edzés hozzáadása vagy módosítása után látod, mi került be, és visszajutsz az űrlap elejére.\n\n## 0.8.1\n\n- A férfi edzőhang mostantól minden eszközön működik: iPhone-on és Macen nem választunk többé vicces hangot, és ahol nincs férfihang a nyelvedhez, a meglévő hangból mélyebbet készítünk.\n- A „Hozzáadás a naptáramhoz” mostantól iPhone-on és iPaden a Naptár alkalmazásban nyílik meg (Safariban koppints az „Összes hozzáadása” gombra).\n\n## 0.8.0\n\n- Teljes képernyő gomb a sávban, ahol a böngésző engedi (iPhone-on nem).\n\n## 0.7.0\n\n- Új hangstílus, az **Őrült**: férfihanggal katonai kiképző, női hanggal parancsolgató főnöknő.\n  Mindkettő végighajt minden sorozaton az edzés végéig.\n- A férfihang mostantól mindig férfiasan szól: ha a telefonodon nincs férfihang a nyelvedhez, az\n  edző mélyebb hangfekvéssel készít egyet (és magasabbal a női hanghoz).\n- Saját gyakorlatok: adj nekik nevet, válaszd ki a mozgást, a mérést, a helyet, a felszerelést\n  és az izmokat. A mozgó figurát automatikusan választjuk. Használd őket a saját terveidben.\n- Emlékeztetők a heti tervedhez: e-mail kezdéskor, vagy 10, 30, illetve 60 perccel előtte, a\n  helyi időd szerint, és naptárfájl a telefonod naptárához.\n- 6 éves kortól gyerekeknek is lehet profiljuk; 12 éves korig könnyebb, saját testsúlyos\n  gyakorlatokat kapnak.\n- Tableten és fekvő telefonon kifér az edzésképernyő: a figura és a gombok egymás mellett\n  vannak, az idő és a haladás fent marad.\n\n## 0.6.0\n\n- Készíts saját edzésterveket: válassz gyakorlatokat, sorozatokat, ismétléseket, időt vagy távot\n  és pihenőket, bármilyen sorrendben. Csak te látod őket, és megmaradnak, amikor a javasolt\n  terveid újra elkészülnek. Bármikor módosíthatod vagy törölheted őket, vagy kiindulhatsz egy\n  javasolt terv másolatából.\n- Heti terv: tegyél edzésterveket egy napszakra, minden napra vagy a hét kiválasztott napjaira,\n  akár többet is egy napon. Az alkalmazás ügyel rá, hogy ne fedjék egymást, a kezdőképernyőd\n  pedig megmutatja a mai tervet egy Indítás gombbal.\n\n## 0.5.0\n\n- Az alkalmazás logója megjelenik a neve mellett az eszköztárban, és ez a böngészőlap ikonja is.\n- Új vagy? Feliratkozás előtt 24 órán át ingyen kipróbálhatod az alkalmazást.\n\n## 0.4.0\n\n- Útmutató, amely az eszköztár **Útmutató** (?) gombjával nyitható meg. Lépésről lépésre\n  elmagyarázza a beállítást, a vezetett edzést, a hangos edzőt, a naptárat, a fejlődési fotókat\n  és a havi e-mailt, és regisztráció előtt is elolvasható.\n\n## 0.3.0\n\n- Hangos edző: edzés közben a telefonod minden gyakorlat előtt és minden pihenő végén\n  visszaszámol, bemondja a sorozatokat, a pihenőket és a következő gyakorlatot, és biztat. Az\n  eszköztáron női vagy férfi hangot és nyugodt, normál vagy motiváló stílust választhatsz, vagy\n  elnémíthatod.\n- Biztató szavak a pihenők alatt és minden edzés után, azzal együtt, mi sikerült jobban, mint\n  legutóbb, és az egyéni csúcsaiddal.\n- Edzésnaptár: nézz meg egy napot, egy hónapot vagy egy évet az időddel, kalóriáddal,\n  sorozataiddal, ismétléseiddel és a sorozatban edzett napjaiddal. Koppints egy napra a\n  részletekért.\n- Fejlődésfotók: a beállításkor (vagy később a profilodban) adj hozzá kezdő fotót, minden\n  hónaphoz és évhez egy fotót, és hasonlítsd össze az előtte és utána képeket. Csak te látod őket.\n- Havi összesítő e-mail minden hónap 1-jén a számaiddal és egy linkkel a naptáradhoz. A\n  profilodban kikapcsolhatod.\n- A javasolt ismétlésszám mostantól attól függ, mennyire nehéz a gyakorlat: húzódzkodásnál\n  kevesebb, vádliemelésnél több.\n- Bejelentkezve maradsz, amíg egy edzés folyamatban van.\n\n## 0.2.0\n\n- Az edzésnapló mostantól edzésterveket készít neked. Add meg a születési éved, a magasságod és\n  a testsúlyod (cm-ben vagy ft-ban, kg-ban vagy lb-ben), a tapasztalatodat és a célodat, és\n  hogy hol edzel: edzőteremben, otthon vagy a szabadban. Otthonra jelöld be, milyen\n  felszerelésed van.\n- Minden helyhez három edzéstervet kapsz, mindegyik bemelegítéssel kezdődik, és látod a\n  becsült időt és kalóriát. A profilodban újra elkészíttetheted őket.\n- Telefonra tervezett, vezetett edzés: egy mozgó figura mutatja a gyakorlatokat, az alkalmazás\n  javasolja az ismétlésszámot, te beírod, mennyit csináltál, és magától lép a következő\n  gyakorlatra, közben pihenőidő-számlálóval.\n- Amit beírsz, 10 másodperc után magától mentődik. Kapcsolat nélkül a telefonodon vár, és\n  elküldjük, amint újra online vagy.\n- Edzés után látod a teljes időt, az egyes gyakorlatok idejét, a kalóriát (becslés) és az\n  alkalmazás javaslatát a következő alkalomra.\n\n## 0.1.1\n\n- Az alkalmazásnak mostantól saját tárhelye van, amely készen áll az edzéseid mentésére.\n  Számodra egyelőre nem változik semmi.\n\n## 0.1.0\n\n- Az edzésnapló első előzetese. A DevQuake-fiókoddal nyitod meg, újabb bejelentkezés nélkül.\n- Egy mintahét mutatja, hogyan fog kinézni az alkalmazás. Következik a saját edzéseid rögzítése.\n"},
};
